def forward(groups):
    date, time = groups
    dt = datetime.strptime(date + time, '%y%m%d%H%M%S')
    return {'stored': [int(dt.timestamp() * 1000000)], 'layout': []}

def inverse(record):
    micros = int(record['stored'][0])
    dt = datetime.fromtimestamp(micros / 1000000)
    return dt.strftime('%y%m%d %H%M%S')

